def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def loc(file,start,end=None):
    p=CH/file; lines=p.read_text(encoding='utf-8').splitlines(); end=end or start
    return {'file':str(p),'start_line':start,'end_line':end,'quote':'\n'.join(lines[start-1:end])}
checks=[]
def ck(file,start,end,reason,source,objection=None):
    checks.append({'id':f'place-s1-{len(checks)+1:02d}',**loc(file,start,end),'decision':'retain','stage1_answer':reason,'source_locator':source,'strongest_reasonable_objection':objection or 'Read with the explicit assumptions in this passage and the preceding setup; no stronger claim is needed for the following argument.'})
ck('05-place-fields.md',3,9,'The opening establishes the observable variety, the statistical target, crossing-based inference, and fixed spatial randomness. It does not claim to predict individual field locations or temporal memory dynamics.','Mainali2025 Introduction, Fig1; supplement S1; earlier 01b-persistence.md lines123-127')
ck('05-place-fields.md',13,22,'The rearrangement example explains why dependence across positions matters. The finite-dimensional definition, mean/covariance functions and jointly Gaussian independence property supply the actual premise of Kac–Rice evaluation. Expectation over cells is explicitly conditional on common statistics.','Mainali2025 supplement S1, printed p8; direct Gaussian identity')
ck('05-place-fields.md',24,32,'Stationarity, isotropy and sample smoothness have separate roles. The nondifferentiable exponential covariance counterexample prevents mistaking Gaussian values for differentiable paths. Invertibility conditions are explained in ordinary words.','Supplement S1/S3 and Taylor2006 regularity framework')
ck('05-place-fields.md',34,50,'Normalization defines q, gain a and units before the excursion set. A connected piece rather than a peak is the field object, which is needed for later topology and peak comparisons. The paper-to-guide symbol mapping prevents conflicts with memory D.','Mainali2025 STAR Methods Eqs2-3; supplement S1')
